  "assessment": {
    "necessary": "yes",
    "necessity_reason": "The added option permits external loading to be suppressed while DTD validation remains selected. An input can request both bits and supply an internal DTD, but the old harness clears XML_PARSE_DTDVALID before every parser route.",
    "before": {
      "requirement": "Parse and validate XML with XML_PARSE_DTDVALID and XML_PARSE_NO_XXE together.",
      "applicability": "not_applicable",
      "harness_status": "not_applicable",
      "reason": "XML_PARSE_NO_XXE is absent from the before parser option enum.",
      "source_evidence": [
        {
          "unit_id": "u-90cc781b5f8cb3ddf3ed",
          "start_line": 1223,
