          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-41acd64ab6c1cad11cac",
          "start_line": 13409,
          "end_line": 13413,
          "role": "dependency",
          "dependency_reason": "The prior DTD validation contract describes external loading without the new suppression option."
        }
      ]
    },
    "after": {
      "requirement": "Parse and validate XML with XML_PARSE_DTDVALID while XML_PARSE_NO_XXE suppresses external DTD and entity loading.",
      "applicability": "required",
      "harness_status": "unsat",
      "reason": "The setter accepts both bits and enables validation from XML_PARSE_DTDVALID. The harness always removes that bit before invoking its parsers, and no shown route restores it.",
