        },
        {
          "unit_id": "u-982d71cee9a79c39eeef",
          "start_line": 13311,
          "end_line": 13355,
          "role": "dependency",
          "dependency_reason": "Accepts both options and sets validation state from XML_PARSE_DTDVALID."
        },
        {
          "unit_id": "u-375771dee8c5d7b8abb8",
          "start_line": 275,
